@Test
    public void testLocaleBranches() throws Exception {
        // This is a logic test for the Locale branch code
        // Case 1: single arg
        String val1 = "en";
        int ix1 = val1.indexOf('_');
        Locale l1 = (ix1 < 0) ? new Locale(val1) : null;
        assertEquals(new Locale("en"), l1);

        // Case 2: two pieces
        String val2 = "en_US";
        int ix2 = val2.indexOf('_');
        String first2 = val2.substring(0, ix2);
        String remaining2 = val2.substring(ix2 + 1);
        int ix3 = remaining2.indexOf('_');
        Locale l2 = (ix3 < 0) ? new Locale(first2, remaining2) : null;
        assertEquals(new Locale("en", "US"), l2);

        // Case 3: three pieces
        String val3 = "en_US_POSIX";
        int ix4 = val3.indexOf('_');
        String first3 = val3.substring(0, ix4);
        String remaining3 = val3.substring(ix4 + 1);
        int ix5 = remaining3.indexOf('_');
        Locale l3 = new Locale(first3, remaining3.substring(0, ix5), remaining3.substring(ix5 + 1));
        assertEquals(new Locale("en", "US", "POSIX"), l3);
    }

