@Test
    public void testInetSocketAddressBranches() throws Exception {
        // Case 1: Bracketed IPv6 with port
        String val1 = "[::1]:80";
        int i1 = val1.lastIndexOf(']');
        int j1 = val1.indexOf(':', i1);
        int port1 = j1 > -1 ? Integer.parseInt(val1.substring(j1 + 1)) : 0;
        InetSocketAddress res1 = new InetSocketAddress(val1.substring(0, i1 + 1), port1);
        assertEquals(80, res1.getPort());
        assertEquals("[::1]", res1.getAddress().getHostAddress().contains("::1") ? "[::1]" : ""); // simplified check

        // Case 2: Bracketed IPv6 without port
        String val2 = "[::1]";
        int i2 = val2.lastIndexOf(']');
        int j2 = val2.indexOf(':', i2);
        int port2 = j2 > -1 ? Integer.parseInt(val2.substring(j2 + 1)) : 0;
        InetSocketAddress res2 = new InetSocketAddress(val2.substring(0, i2 + 1), port2);
        assertEquals(0, res2.getPort());

        // Case 3: Host:Port (IPv4 or hostname)
        String val3 = "localhost:8080";
        int ix3 = val3.indexOf(':');
        int port3 = Integer.parseInt(val3.substring(ix3 + 1));
        InetSocketAddress res3 = new InetSocketAddress(val3.substring(0, ix3), port3);
        assertEquals("localhost", res3.getHostString());
        assertEquals(8080, res3.getPort());

        // Case 4: Host only
        String val4 = "127.0.0.1";
        int ix4 = val4.indexOf(':');
        InetSocketAddress res4 = (ix4 >= 0 && val4.indexOf(':', ix4 + 1) < 0) 
            ? new InetSocketAddress(val4.substring(0, ix4), Integer.parseInt(val4.substring(ix4+1)))
            : new InetSocketAddress(val4, 0);
        assertEquals("127.0.0.1", res4.getHostString());
        assertEquals(0, res4.getPort());
    }

