@Test
    public void testToStringSingleValue() {
        SummaryStatistics stats = new SummaryStatistics();
        stats.addValue(10.0);

        String result = stats.toString();

        // With one value, variance/std dev should be NaN (unbiased estimator requires n > 1)
        StringBuilder expected = new StringBuilder();
        expected.append("SummaryStatistics:\n");
        expected.append("n: 1\n");
        expected.append("min: 10.0\n");
        expected.append("max: 10.0\n");
        expected.append("mean: 10.0\n");
        expected.append("geometric mean: 10.0\n");
        expected.append("variance: ").append(stats.getVariance()).append("\n");
        expected.append("sum of squares: 100.0\n");
        expected.append("standard deviation: ").append(stats.getStandardDeviation()).append("\n");
        expected.append("sum of logs: ").append(stats.getSumOfLogs()).append("\n");

        assertEquals(expected.toString(), result);
    }

